/// Resolve a `target: Option<u8>` slot index against `state.enemy_uids`.
/// Returns `None` when the slot is out of range or the target arg is
/// missing (e.g. enemy died between `legal_actions` enumeration and
/// drink resolution). Used by enemy-target potions (Weak / Vulnerable).
///
/// NOTE: the `target` reaching here from `apply(Action::DrinkPotion)` is
/// already a concrete RAW `enemy_uids` index — that arm resolves a `None`
/// target to the first alive enemy's raw index (lib.rs, the C#
/// `DoUsePotion` auto-target) BEFORE dispatching the effect — so this
/// helper indexes `enemy_uids` directly and must NOT re-filter to an
/// alive-only list (that would reinterpret the raw index against a shorter
/// list and mis-target when a dead enemy precedes a live one). Bead
/// `sts2-rs-wdf8`.
pub(crate) fn resolve_enemy_target(
    state: &CombatState,
    target: Option<u8>,
) -> Option<sts2_core::CreatureUid> {
    let idx = usize::from(target?);
    state.enemy_uids.get(idx).copied()
}

