/// Shared body for the three character-pool choose-a-card potions.
/// Samples [`CARD_GEN_POTION_CANDIDATES`] distinct `card_type` ids from
/// the player's character pool (off `Rng.CombatCardGeneration`) and
/// opens an `AddGeneratedFreeToHand` choice (min 1 / max 1, skippable —
/// C# `canSkip: true`); the resolver materialises only the chosen card,
/// stamps it free-this-turn, and routes it to hand. No-op if the player
/// has no character set or their pool has no `*_SPECS` slice yet
/// (Regent/Necrobinder). Bead `sts2-rs-91tc1`.
pub(crate) fn drink_character_card_potion(
    state: &mut CombatState,
    card_type: sts2_core::cards::CardType,
) -> EffectResult {
    let Some(character) = state.player.character else {
        return EffectResult::Resolved;
    };
    let ids = crate::cards::colorless::distinct_character_card_ids(
        state,
        character,
        Some(card_type),
        CARD_GEN_POTION_CANDIDATES,
    );
    open_generated_free_choice(state, ids.as_slice());
    EffectResult::Resolved
}

/// Open an `AddGeneratedFreeToHand` choose-a-card screen over the given
/// candidate card ids (single-pick, skippable — C# `canSkip: true`).
/// No-op when no candidates were produced (empty pool / no character).
/// The chosen card is materialised + stamped free-this-turn by
/// [`sts2_core::ChoiceKind::AddGeneratedFreeToHand`]'s resolver. Bead
/// `sts2-rs-91tc1`.
pub(crate) fn open_generated_free_choice(
    state: &mut CombatState,
    ids: &[sts2_core::cards::CardId],
) {
    if ids.is_empty() {
        return;
    }
    let options: Vec<sts2_core::ChoiceOption> = ids
        .iter()
        .map(|&card_id| sts2_core::ChoiceOption {
            card_id,
            upgraded: false,
            card_uid: None,
            source_pile: None,
        })
        .collect();
    state.request_card_choice(
        sts2_core::ChoiceKind::AddGeneratedFreeToHand,
        options,
        1,
        1,
        true,
    );
}

